// Builds apps/web/static/css/forum.css and debug.css from apps/web/frontend/styles (docs/styles.md, "Where styles
// live"). The colors are not part of forum.css: every skin's stylesheet carries its palette, generated by the server
// from themes/default.json and the skin's overrides (docs/skins.md).
//
// forum.css declares the cascade layers first (docs/skins.md, "Cascade layers"):
//   guards  guards.css, plus copies of the header sizes and focus rings that only hold under built-in skins
//   core    index.css and everything it imports
//   skin    the skin's palettes and stylesheet (/skin/<id>.css)
//   member  a member's personal style (/my/style.css)
import { build } from 'esbuild';
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const source = resolve('apps/web/frontend/styles');

/** The text with every comment replaced by a space (strings are kept as they are). */
function uncomment(css) {
  let out = '';
  let i = 0;
  while (i < css.length) {
    const c = css[i];
    if (c === '/' && css[i + 1] === '*') {
      const end = css.indexOf('*/', i + 2);
      if (end < 0) throw new Error('unclosed comment');
      out += ' ';
      i = end + 2;
    } else if (c === '"' || c === "'") {
      const end = css.indexOf(c, i + 1);
      if (end < 0) throw new Error('unclosed string');
      out += css.slice(i, end + 1);
      i = end + 1;
    } else {
      out += c;
      i += 1;
    }
  }
  return out;
}

/** Splits comment-free CSS into top-level blocks, { prelude, body }; statements such as @import are skipped. */
function items(css) {
  const found = [];
  let start = 0;
  let i = 0;
  const skipString = at => {
    const end = css.indexOf(css[at], at + 1);
    if (end < 0) throw new Error('unclosed string');
    return end + 1;
  };
  while (i < css.length) {
    const c = css[i];
    if (c === '"' || c === "'") {
      i = skipString(i);
    } else if (c === ';') {
      start = i + 1;
      i += 1;
    } else if (c === '{') {
      let depth = 1;
      let j = i + 1;
      while (depth > 0) {
        if (j >= css.length) throw new Error('unclosed block');
        const d = css[j];
        if (d === '"' || d === "'") {
          j = skipString(j);
          continue;
        }
        if (d === '{') depth += 1;
        if (d === '}') depth -= 1;
        j += 1;
      }
      found.push({ prelude: css.slice(start, i).trim(), body: css.slice(i + 1, j - 1) });
      i = j;
      start = j;
    } else {
      i += 1;
    }
  }
  return found;
}

/** Splits at commas outside brackets and quotes. */
function splitTop(text, separator = ',') {
  const parts = [];
  let depth = 0;
  let quote = null;
  let start = 0;
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    if (quote) { if (c === quote) quote = null; continue; }
    if (c === '"' || c === "'") quote = c;
    else if (c === '(' || c === '[') depth += 1;
    else if (c === ')' || c === ']') depth -= 1;
    else if (c === separator && depth === 0) { parts.push(text.slice(start, i)); start = i + 1; }
  }
  parts.push(text.slice(start));
  return parts.map(part => part.trim()).filter(Boolean);
}

/** Declarations of a rule body as [property, value]. */
function declarations(body) {
  return splitTop(body, ';').map(part => {
    const colon = part.indexOf(':');
    return [part.slice(0, colon).trim().toLowerCase(), part.slice(colon + 1).trim()];
  }).filter(([property]) => property);
}

// The header sizes router/nav_fit.rs estimates widths from (docs/styles.md, "Header navigation widths"), and the
// focus rings of docs/styles.md, "HTML conventions". Built-in skins may change neither; imported and instance skins
// get a warning instead (docs/skins.md, "Two kinds of rules"), so the copies only apply under built-in skins.
const MASTHEAD = /(^|[^a-z0-9_-])(masthead[a-z0-9_-]*|forum-more[a-z0-9_-]*|theme-switch[a-z0-9_-]*)|\.container(?![a-z0-9_-])/;
const sizeProperty = property => /^(padding|margin)(-|$)/.test(property)
  || ['font', 'font-size', 'letter-spacing', 'word-spacing', 'gap', 'column-gap', 'row-gap', 'width', 'inline-size',
    'min-width', 'min-inline-size', 'max-width', 'max-inline-size', 'flex-basis'].includes(property)
  || /^border(-(block|inline|top|right|bottom|left)(-(start|end))?)?(-width)?$/.test(property);
const focusProperty = property => /^outline(-(width|style|color|offset))?$/.test(property);
const BUILTIN = ':root[data-skin-source="builtin"]';

/** The border width a border shorthand sets: its length, 0 for none, medium when it names none. */
function borderWidth(value) {
  const words = value.split(/\s+/);
  const width = words.find(word => /^(-?\d*\.?\d+(px|em|rem)?|thin|medium|thick)$/.test(word));
  if (width) return width;
  return words.includes('none') || words.includes('hidden') ? '0' : 'medium';
}

/** The guard copies of one stylesheet, keeping its order and @media conditions. */
function copies(css, media = null) {
  let out = '';
  for (const { prelude, body } of items(css)) {
    if (prelude.startsWith('@media')) {
      const inner = copies(body, prelude);
      if (inner) out += inner;
      continue;
    }
    if (prelude.startsWith('@')) continue;
    const selectors = splitTop(prelude);
    const rules = [
      [selectors.filter(selector => /:focus/.test(selector)), focusProperty],
      [selectors.filter(selector => MASTHEAD.test(selector)), sizeProperty],
    ];
    for (const [chosen, wanted] of rules) {
      if (!chosen.length) continue;
      const kept = declarations(body).filter(([property]) => wanted(property)).map(([property, value]) => {
        const shorthand = /^border(-(block|inline|top|right|bottom|left)(-(start|end))?)?$/.test(property);
        return shorthand ? [`${property}-width`, borderWidth(value)] : [property, value];
      });
      if (!kept.length) continue;
      const rule = `${chosen.map(selector => `${BUILTIN} ${selector}`).join(',\n')} {\n${kept.map(([property, value]) => `  ${property}: ${value.replace(/\s*!important$/, '')} !important;`).join('\n')}\n}\n`;
      out += media ? `${media} {\n${rule}}\n` : rule;
    }
  }
  return out;
}

const imports = [...(await readFile(resolve(source, 'index.css'), 'utf8')).matchAll(/@import\s+"\.\/([^"]+)";/g)].map(match => match[1]);
let builtinGuards = '/* Built-in skins only (generated from the core stylesheets by scripts/build-styles.mjs). */\n';
for (const file of imports) {
  const copied = copies(uncomment(await readFile(resolve(source, file), 'utf8')));
  if (copied) builtinGuards += `/* ${file} */\n${copied}`;
}

await build({
  stdin: {
    contents: '@layer guards, core, skin, member;\n@import "./guards.css" layer(guards);\n@import "forum:builtin-guards" layer(guards);\n@import "./index.css" layer(core);\n',
    resolveDir: source,
    loader: 'css',
  },
  plugins: [{ name: 'forum-guards', setup(api) {
    api.onResolve({ filter: /^forum:builtin-guards$/ }, () => ({ path: 'builtin-guards', namespace: 'forum' }));
    api.onLoad({ filter: /.*/, namespace: 'forum' }, () => ({ contents: builtinGuards, loader: 'css' }));
  } }],
  outfile: 'apps/web/static/css/forum.css',
  bundle: true, minify: false, charset: 'utf8', logLevel: 'info',
});
await build({
  entryPoints: [resolve(source, 'debug.css')],
  outfile: 'apps/web/static/css/debug.css',
  bundle: true, minify: false, charset: 'utf8', logLevel: 'info',
});
